/*
 * Fade — LED brightness fade using PWM
 */

int ledPin = 9;

void setup() {
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // fade in
  for (int i = 0; i <= 255; i++) {
    analogWrite(ledPin, i);
    delay(5);
  }
  // fade out
  for (int i = 255; i >= 0; --i) {
    analogWrite(ledPin, i);
    delay(5);
  }
}
